 45	function validateTask(value: unknown): value is Task {
 46	  if (!isRecord(value)) return false;
 47	  const allowed = new Set(["id", "title", "status", "tags", "due", "createdAt", "completedAt"]);
 48	  if (Object.keys(value).some((key) => !allowed.has(key))) return false;
 49	  if (!Number.isSafeInteger(value.id) || (value.id as number) < 1) return false;
 50	  if (typeof value.title !== "string" || value.title.trim() === "") return false;
 51	  if (value.status !== "open" && value.status !== "done") return false;
 52	  if (!Array.isArray(value.tags) || !value.tags.every((tag) => typeof tag === "string" && tag !== "")) return false;
 53	  if (new Set(value.tags).size !== value.tags.length) return false;
 54	  if (value.tags.some((tag) => tag !== tag.trim().toLowerCase())) return false;
 55	  if (value.due !== undefined && !isDate(value.due)) return false;
 56	  if (!isIsoTimestamp(value.createdAt)) return false;
 57	  if (value.status === "done" && !isIsoTimestamp(value.completedAt)) return false;
 58	  if (value.status === "open" && value.completedAt !== undefined) return false;
 59	  return true;
 60	}
