 62	function validateDatabase(value: unknown): value is Database {
 63	  if (!isRecord(value)) return false;
 64	  if (Object.keys(value).some((key) => !["version", "nextId", "tasks"].includes(key))) return false;
 65	  if (value.version !== 1 || !Number.isSafeInteger(value.nextId) || (value.nextId as number) < 1) return false;
 66	  if (!Array.isArray(value.tasks) || !value.tasks.every(validateTask)) return false;
 67	  const ids = value.tasks.map((task) => task.id);
 68	  if (new Set(ids).size !== ids.length) return false;
 69	  return ids.every((id) => id < (value.nextId as number));
 70	}
