 72	async function loadDatabase(): Promise<Database> {
 73	  let text: string;
 74	  try {
 75	    text = await Bun.file(databasePath).text();
 76	  } catch (error) {
 77	    if (isRecord(error) && error.code === "ENOENT") return { version: 1, nextId: 1, tasks: [] };
 78	    fail(`cannot read database: ${error instanceof Error ? error.message : String(error)}`);
 79	  }
 80	
 81	  let value: unknown;
 82	  try {
 83	    value = JSON.parse(text);
 84	  } catch {
 85	    fail("database is malformed: invalid JSON");
 86	  }
 87	  if (!validateDatabase(value)) fail("database is malformed: invalid structure");
 88	  return value;
 89	}
