 91	async function saveDatabase(database: Database): Promise<void> {
 92	  const directory = dirname(databasePath);
 93	  const temporary = resolve(directory, `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`);
 94	  try {
 95	    await writeFile(temporary, `${JSON.stringify(database, null, 2)}\n`, { encoding: "utf8", flag: "wx" });
 96	    await rename(temporary, databasePath);
 97	  } catch (error) {
 98	    try {
 99	      await unlink(temporary);
100	    } catch {
101	      // There may be no temporary file to clean up.
102	    }
103	    fail(`cannot write database: ${error instanceof Error ? error.message : String(error)}`);
104	  }
105	}
