107	function parseFlags(args: string[], permitted: Set<string>): Record<string, string> {
108	  const values: Record<string, string> = {};
109	  for (let index = 0; index < args.length; index += 1) {
110	    const token = args[index];
111	    if (!token.startsWith("--")) fail(`unexpected argument: ${token}`);
112	    const equals = token.indexOf("=");
113	    const name = equals === -1 ? token.slice(2) : token.slice(2, equals);
114	    if (!permitted.has(name)) fail(`unknown flag: --${name}`);
115	    if (name in values) fail(`duplicate flag: --${name}`);
116	    const value = equals === -1 ? args[++index] : token.slice(equals + 1);
117	    if (value === undefined || (equals === -1 && value.startsWith("--"))) fail(`missing value for --${name}`);
118	    values[name] = value;
119	  }
120	  return values;
121	}
