133	function parseId(value: string | undefined): number {
134	  if (value === undefined || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
135	  const id = Number(value);
136	  if (!Number.isSafeInteger(id)) fail("ID must be a safe positive integer");
137	  return id;
138	}
