140	function localToday(): string {
141	  const now = new Date();
142	  const year = now.getFullYear();
143	  const month = String(now.getMonth() + 1).padStart(2, "0");
144	  const day = String(now.getDate()).padStart(2, "0");
145	  return `${year}-${month}-${day}`;
146	}
