148	async function run(args: string[]): Promise<unknown> {
149	  const [command, ...rest] = args;
150	  if (!command) fail("missing command");
151	
152	  if (command === "add") {
153	    const flags = parseFlags(rest, new Set(["title", "tags", "due"]));
154	    if (!("title" in flags)) fail("missing required flag: --title");
155	    const title = flags.title.trim();
156	    if (!title) fail("title must not be empty");
157	    const database = await loadDatabase();
158	    const task: Task = {
159	      id: database.nextId,
160	      title,
161	      status: "open",
162	      tags: normalizedTags(flags.tags),
163	      createdAt: new Date().toISOString(),
164	    };
165	    if (flags.due !== undefined) task.due = requireDate(flags.due, "due");
166	    database.tasks.push(task);
167	    database.nextId += 1;
168	    await saveDatabase(database);
169	    return task;
170	  }
171	
172	  if (command === "list") {
173	    const flags = parseFlags(rest, new Set(["status", "tag", "overdue"]));
174	    if (flags.status !== undefined && flags.status !== "open" && flags.status !== "done") {
175	      fail(`invalid status: ${flags.status}`);
176	    }
177	    const tag = flags.tag?.trim().toLowerCase();
178	    if (flags.tag !== undefined && !tag) fail("tag must not be empty");
179	    const overdue = flags.overdue === undefined ? undefined : requireDate(flags.overdue, "overdue");
180	    const database = await loadDatabase();
181	    return database.tasks
182	      .filter((task) => flags.status === undefined || task.status === flags.status)
183	      .filter((task) => tag === undefined || task.tags.includes(tag))
184	      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
185	      .sort((left, right) => left.id - right.id);
186	  }
187	
188	  if (command === "done") {
189	    if (rest.length !== 1) fail("usage: done ID");
190	    const id = parseId(rest[0]);
191	    const database = await loadDatabase();
192	    const task = database.tasks.find((candidate) => candidate.id === id);
193	    if (!task) fail(`task not found: ${id}`);
194	    if (task.status === "open") {
195	      task.status = "done";
196	      task.completedAt = new Date().toISOString();
197	      await saveDatabase(database);
198	    }
199	    return task;
200	  }
201	
202	  if (command === "delete") {
203	    if (rest.length !== 1) fail("usage: delete ID");
204	    const id = parseId(rest[0]);
205	    const database = await loadDatabase();
206	    const index = database.tasks.findIndex((candidate) => candidate.id === id);
207	    if (index === -1) fail(`task not found: ${id}`);
208	    database.tasks.splice(index, 1);
209	    await saveDatabase(database);
210	    return { deleted: id };
211	  }
212	
213	  if (command === "stats") {
214	    if (rest.length !== 0) fail("stats does not accept arguments");
215	    const database = await loadDatabase();
216	    const today = localToday();
217	    const open = database.tasks.filter((task) => task.status === "open").length;
218	    return {
219	      total: database.tasks.length,
220	      open,
221	      done: database.tasks.length - open,
222	      overdue: database.tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length,
223	    };
224	  }
225	
226	  fail(`unknown command: ${command}`);
227	}
