229	try {
230	  const result = await run(Bun.argv.slice(2));
231	  process.stdout.write(`${JSON.stringify(result)}\n`);
232	} catch (error) {
233	  const message = error instanceof Error ? error.message : String(error);
234	  process.stdout.write(`${JSON.stringify({ error: message })}\n`);
235	  process.stderr.write(`taskboard: ${message}\n`);
236	  process.exitCode = 1;
237	}
